    /**
     * @return array<string, array<string, mixed>>
     */
    public static function all(): array
    {
        static $events = null;

        if ($events === null) {
            $events = [];

            foreach (self::SECTIONS as $section) {
                $events += $section::events();
            }
        }

        return $events;
    }

    /**
     * @return array<string, mixed>|null
     */
    public static function find(string $event): ?array
    {
        return self::all()[$event] ?? null;
    }

    /**
     * @return array<string, mixed>
     */
    public static function get(string $event): array
    {
        return self::find($event) ?? throw new InvalidArgumentException("Unknown email event [{$event}]. Add it to the email catalogue.");
    }

    public static function category(string $event): EmailCategory
    {
        return self::get($event)['category'];
    }

    /**
     * @return array<string, string>
     */
    public static function sample(string $event): array
    {
        return collect(self::get($event)['variables'])->mapWithKeys(fn (string $variable): array => [$variable => self::SAMPLES[$variable] ?? '['.$variable.']'])->all();
    }

    /**
     * @return array<string, array<string, array<string, mixed>>>
     */
    public static function byActor(): array
    {
        $grouped = array_fill_keys(array_keys(self::ACTORS), []);

        foreach (self::all() as $key => $event) {
            $grouped[$event['actor']][$key] = $event;
        }

        return $grouped;
    }
}
